WITH lines AS (SELECT id, plan, effective_from, currency, val FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) e AS val) SELECT CASE WHEN val >= 69 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_tier, DATE_TRUNC('MONTH', effective_from) AS activity_month, ROUND(AVG(val), 2) AS avg_val, SIZE(COLLECT_SET(currency)) AS num_currencies, PERCENTILE_APPROX(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles FROM lines GROUP BY GROUPING SETS ((CASE WHEN val >= 69 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('MONTH', effective_from)), (CASE WHEN val >= 69 THEN 'PREMIUM' ELSE 'STANDARD' END)) ORDER BY avg_val DESC;
